\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='2s'; SET LOCAL timezone='UTC';
DO $identity$ BEGIN
 IF current_database()<>'verdify_rehearsal' OR current_setting('cluster_name')<>'verdify-cnpg-s2-integration'
 OR current_setting('server_version_num')::int<>160013 OR inet_client_addr() IS NOT NULL
 OR pg_is_in_recovery() OR current_user<>'postgres' OR session_user<>'postgres'
 OR (SELECT oid FROM pg_database WHERE datname=current_database())<>16447
 OR (SELECT system_identifier::text FROM pg_control_system())<>'7693399121498484768'
 THEN RAISE EXCEPTION '382 metadata refuses changed integration identity'; END IF;
END $identity$;
SELECT jsonb_build_object('kind','identity','database',current_database(),'database_oid',(SELECT oid FROM pg_database WHERE datname=current_database()),'system_identifier',(SELECT system_identifier::text FROM pg_control_system()),'cluster_name',current_setting('cluster_name'),'server_version_num',current_setting('server_version_num')::int,'primary',NOT pg_is_in_recovery(),'timescaledb',(SELECT extversion FROM pg_extension WHERE extname='timescaledb'),'vector',(SELECT extversion FROM pg_extension WHERE extname='vector'),'timescaledb_max_background_workers',current_setting('timescaledb.max_background_workers'),'transaction_read_only',current_setting('transaction_read_only'),'backend_pid',pg_backend_pid());
SELECT jsonb_build_object('kind','role_posture','roles',jsonb_agg(jsonb_build_object('role',r.rolname,'login',r.rolcanlogin,'inherit',r.rolinherit,'password_null',r.rolpassword IS NULL,'super',r.rolsuper,'create_db',r.rolcreatedb,'create_role',r.rolcreaterole,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls,'memberships',(SELECT jsonb_agg(jsonb_build_object('role',p.rolname,'admin_option',a.admin_option,'inherit_option',a.inherit_option,'set_option',a.set_option) ORDER BY p.rolname) FROM pg_auth_members a JOIN pg_roles p ON p.oid=a.roleid WHERE a.member=r.oid)) ORDER BY r.rolname)) FROM pg_authid r WHERE r.rolname IN ('verdify_ingestor_runtime_login','verdify_experiment_v2_equipment_source_collector_login');
SELECT jsonb_build_object('kind','ordinary_ingestor_boundary','sha256',encode(public.fn_runtime_ordinary_boundary_digest('verdify_ingestor_runtime_login'),'hex'));
SELECT jsonb_build_object('kind','functions','functions',jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'acl',p.proacl::text) ORDER BY p.oid::regprocedure::text)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('fn_record_equipment_counter_sample','fn_record_equipment_direct_state_snapshot','fn_record_equipment_state_source_receipt','fn_record_climate_source_event','fn_record_observational_source_event');
SELECT jsonb_build_object('kind','immutable_trigger','enabled',tgenabled,'function_sha256',encode(sha256(convert_to(pg_get_functiondef(tgfoid),'UTF8')),'hex')) FROM pg_trigger WHERE tgrelid='public.equipment_state_source_receipts'::regclass AND tgname='trg_equipment_state_source_receipts_immutable';
SELECT jsonb_build_object('kind','migration_metadata','source_migrations',count(*) FILTER (WHERE source='db/migrations'),'max_seq',max(seq) FILTER (WHERE source='db/migrations'),'ledger_row_hashes_sha256',encode(sha256(convert_to(string_agg(to_jsonb(t)::text,E'\n' ORDER BY source,seq,filename),'UTF8')),'hex'),'275',(SELECT jsonb_agg(jsonb_build_object('filename',filename,'source',source,'seq',seq,'sha256',sha256,'stamp_method',stamp_method)) FROM public.schema_migrations WHERE source='db/migrations' AND seq=275)) FROM public.schema_migrations t;
SELECT jsonb_build_object('kind','native_admission_metadata','rows',jsonb_agg(jsonb_build_array(login_name,encode(boundary_sha256,'hex'),qualification_sha256) ORDER BY login_name)) FROM public.cnpg_s2_275_runtime_receipts;
SELECT jsonb_build_object('kind','active_sessions','sessions',coalesce(jsonb_agg(jsonb_build_object('pid',pid,'user',usename,'application',application_name,'client_address',client_addr,'backend_type',backend_type,'state',state,'transaction_start',xact_start) ORDER BY pid),'[]'::jsonb)) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid();
SELECT jsonb_build_object('kind','year2000_chunk_inventory','chunks',coalesce(jsonb_agg(jsonb_build_object('table',hypertable_name,'schema',chunk_schema,'chunk',chunk_name,'range_start',range_start,'range_end',range_end) ORDER BY hypertable_name,chunk_schema,chunk_name),'[]'::jsonb)) FROM timescaledb_information.chunks WHERE hypertable_schema='public' AND hypertable_name IN ('climate','diagnostics','equipment_state') AND range_start<'2000-02-01'::timestamptz AND range_end>'1999-12-01'::timestamptz;
SELECT jsonb_build_object('kind','sequence_count','count',count(*)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='S' AND n.nspname!~'^pg_' AND n.nspname<>'information_schema';
SELECT format('SELECT jsonb_build_object(''kind'',''sequence'',''name'',%L,''last_value'',last_value,''is_called'',is_called) FROM %I.%I;',format('%I.%I',n.nspname,c.relname),n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='S' AND n.nspname!~'^pg_' AND n.nspname<>'information_schema' ORDER BY n.nspname,c.relname
\gexec
COMMIT;
